  const fmtDate=v=>{if(!v)return '';const d=new Date(`${String(v).slice(0,10)}T00:00:00`);return new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'long',day:'numeric'}).format(d)};
  const fmtShort=v=>{if(!v)return '';const d=new Date(`${String(v).slice(0,10)}T00:00:00`);return `${d.getMonth()+1}.${d.getDate()}`};
  const fmtTime=v=>v?new Intl.DateTimeFormat('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'';
  const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const money=n=>'₩'+Math.round(Number(n)||0).toLocaleString('ko-KR');
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const state={profile:null,page:'today',labTab:'ideas',squareTab:'discover',settingsTab:'profile',records:[],recordUrls:new Map(),recordEdit:null,newRecordFiles:[],calendarView:new Date(),selectedDay:new Date(),calendarEvents:[],habits:[],habitChecks:[],goals:[],projects:[],ideas:[],works:[],finance:[],ownPublications:[],publishTarget:null,projectEdit:null,currentPub:null,comments:[],reportTarget:null,draftTimer:null,networkOnline:navigator.onLine,eventEdit:null,habitEdit:null,lightboxUrls:[],lightboxIndex:0};
  state.calendarView.setDate(1);

  function toast(message,action){const host=$('#toastStack');if(!host)return;const el=document.createElement('div');el.className='toast';const text=document.createElement('span');text.textContent=message;el.appendChild(text);if(action){const b=document.createElement('button');b.className='toast-action';b.type='button';b.textContent=action.label||'다시 시도';b.addEventListener('click',async()=>{el.remove();await action.run()});el.appendChild(b)}host.appendChild(el);setTimeout(()=>el.remove(),action?6000:2800)}
  function setBusy(el,on,label){if(!el)return;if(on){el.dataset.original=el.textContent;el.disabled=true;el.classList.add('loading');if(label)el.textContent=label}else{el.disabled=false;el.classList.remove('loading');if(el.dataset.original){el.textContent=el.dataset.original;delete el.dataset.original}}}
  function syncUI(text,ok=true){const el=$('#syncState');if(!el)return;el.querySelector('span').textContent=text;el.querySelector('i').style.background=ok?'#7ca18d':'#b66a63'}
  function openModal(id){const el=$('#'+id);if(el){el.classList.add('show');el.setAttribute('aria-hidden','false')}}
  function closeModal(id){const el=$('#'+id);if(el){el.classList.remove('show');el.setAttribute('aria-hidden','true')}}
