    const safeName=name||'';$('#authShell').classList.add('hidden');$('#appShell').classList.add('hidden');$('#onboardingShell').classList.remove('hidden');
    $('#onboardingName').value=safeName;$('#onboardingLabName').value=(p?.lab_name&&p.lab_name!=='나의 연구실')?p.lab_name:(safeName?`${safeName}의 연구실`:'');updateOnboardingPreview();
