  async function deleteRecord(id){if(!confirm('이 기록과 첨부 사진을 삭제할까요?'))return;const r=state.records.find(x=>x.id===id),paths=(r?.record_media||[]).map(m=>m.storage_path);try{await withError(()=>DB.deleteRecord(id),'기록 삭제');let cleanupFailed=false;if(paths.length)try{await Storage.removePrivatePaths(paths)}catch(e){cleanupFailed=true;console.warn(e)}await loadRecords();toast(cleanupFailed?'기록은 삭제됐고, 일부 파일 정리는 다음 점검에서 다시 확인합니다.':'기록을 삭제했습니다.')}catch{}}

  function monthBounds(view){const start=new Date(view.getFullYear(),view.getMonth(),1),end=new Date(view.getFullYear(),view.getMonth()+1,0);return[dateKey(start),dateKey(end)]}
  function calendarGridBounds(view){const first=new Date(view.getFullYear(),view.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());const end=new Date(start);end.setDate(start.getDate()+41);return[dateKey(start),dateKey(end)]}
  async function loadCalendar(){const [monthStart,monthEnd]=monthBounds(state.calendarView),[gridStart,gridEnd]=calendarGridBounds(state.calendarView);const [events,habits,checks,goals]=await withError(()=>Promise.all([DB.listEventsForMonth(monthStart,monthEnd),DB.listHabits(),DB.checksForRange(gridStart,gridEnd),DB.loadGoals(state.calendarView)]),'캘린더 불러오기');state.calendarEvents=events;state.habits=habits;state.habitChecks=checks;state.goals=goals;renderCalendar();renderSelectedDay();renderGoalInputs()}
  function renderWeeklyFocus(){const d=new Date(state.selectedDay),monday=new Date(d);monday.setDate(d.getDate()-((d.getDay()+6)%7));const days=[...Array(7)].map((_,i)=>{const x=new Date(monday);x.setDate(monday.getDate()+i);return dateKey(x)}),checks=state.habitChecks.filter(c=>days.includes(c.day)&&c.completed);const total=state.habits.reduce((sum,h)=>sum+(h.schedule?.type==='weekly_n'?Number(h.schedule.count)||1:h.schedule?.type==='weekdays'?5:h.schedule?.type==='selected_weekdays'?(h.schedule.days||[]).length:7),0),done=checks.length;$('#weeklyFocus').innerHTML=`<div class="card-head"><h3>주간 Focus</h3><small>${fmtShort(days[0])} ~ ${fmtShort(days[6])}</small></div><p>이번 주 체크리스트 <strong>${done}</strong>회 완료 · 목표 ${total}회</p><div class="progress"><i style="width:${total?Math.min(100,done/total*100):0}%"></i></div>`}
  function moveCalendar(n){state.calendarView.setMonth(state.calendarView.getMonth()+n);state.calendarView.setDate(1);state.selectedDay=new Date(state.calendarView);loadCalendar().catch(()=>{})}
  function renderCalendar(){const v=state.calendarView,first=new Date(v.getFullYear(),v.getMonth(),1),offset=first.getDay(),start=new Date(v.getFullYear(),v.getMonth(),1-offset),today=DB.today();$('#calendarMonth').textContent=`${v.getFullYear()}년 ${v.getMonth()+1}월`;let out='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const k=dateKey(d),outside=d.getMonth()!==v.getMonth(),events=state.calendarEvents.filter(e=>e.start_date<=k&&e.end_date>=k),range=events.some(e=>e.start_date!==e.end_date),checks=state.habitChecks.filter(c=>c.day===k&&c.completed).length;const eventHtml=events.slice(0,2).map(e=>{const s=e.start_date===k,t=e.end_date===k;return `<span class="day-event ${s?'range-start':''} ${t?'range-end':''} ${!s&&!t?'range-mid':''}"><span>${s||e.start_date===e.end_date?esc(e.name):' '}</span></span>`}).join('');out+=`<button class="day ${outside?'outside':''} ${k===today?'today':''} ${k===dateKey(state.selectedDay)?'selected':''} ${range?'range-day':''}" data-select-day="${k}"><span class="day-number">${d.getDate()}</span><div class="day-dots">${eventHtml}</div>${checks?'<span class="day-habit-dot"></span>':''}</button>`}$('#calendarDays').innerHTML=out}
  function checksMapFor(day){return new Map(state.habitChecks.filter(c=>c.day===day).map(c=>[c.habit_id,c.completed]))}
  const habitScheduleLabel=s=>s?.type==='weekdays'?'평일':s?.type==='selected_weekdays'?`선택 요일 ${(s.days||[]).map(d=>['일','월','화','수','목','금','토'][d]).join('·')}`:s?.type==='weekly_n'?`주 ${s.count||1}회`:'매일';
  const habitRunsOn=(day,s)=>{if(!s||s.type==='daily'||s.type==='weekly_n')return true;const dow=new Date(`${day}T00:00:00`).getDay();return s.type==='weekdays'?dow>=1&&dow<=5:(s.days||[]).includes(dow)};
  function habitScheduleValue(){const type=$('#habitSchedule').value;if(type==='weekly_n')return{type,count:clamp(Number($('#habitWeeklyCount').value)||1,1,7)};if(type==='selected_weekdays'){const days=$$('#habitWeekdayPicker input:checked').map(x=>Number(x.value));return{type,days:days.length?days:[1]}}return{type}}
  function resetHabitEditor(){state.habitEdit=null;$('#habitNewName').value='';$('#habitSchedule').value='daily';$('#habitWeeklyCount').value='3';$('#habitWeeklyCountWrap').classList.add('hidden');$('#habitWeekdayPicker').classList.add('hidden');$$('#habitWeekdayPicker input').forEach(x=>x.checked=false);$('#habitAdd').textContent='추가';$('#habitCancel').classList.add('hidden')}
  function startHabitEdit(id){const h=state.habits.find(x=>x.id===id);if(!h)return;state.habitEdit=h;$('#habitNewName').value=h.name;$('#habitSchedule').value=h.schedule?.type||'daily';$('#habitWeeklyCount').value=h.schedule?.count||3;$('#habitWeeklyCountWrap').classList.toggle('hidden',$('#habitSchedule').value!=='weekly_n');$('#habitWeekdayPicker').classList.toggle('hidden',$('#habitSchedule').value!=='selected_weekdays');$$('#habitWeekdayPicker input').forEach(x=>x.checked=(h.schedule?.days||[]).includes(Number(x.value)));$('#habitAdd').textContent='수정 저장';$('#habitCancel').classList.remove('hidden');$('#habitNewName').focus()}
  function renderSelectedDay(){const day=dateKey(state.selectedDay),events=state.calendarEvents.filter(e=>e.start_date<=day&&e.end_date>=day),checks=checksMapFor(day);$('#selectedDayTitle').textContent=fmtDate(day);if(!state.eventEdit){$('#eventStart').value=day;$('#eventEnd').value=day}$('#selectedEvents').innerHTML=events.length?events.map(e=>`<div class="event-row"><button class="check ${e.done?'done':''}" data-event-toggle="${e.id}" data-done="${e.done}">${e.done?'✓':''}</button><div class="event-copy"><strong>${esc(e.name)}</strong><span>${fmtShort(e.start_date)}${e.end_date!==e.start_date?` ~ ${fmtShort(e.end_date)}`:''}</span></div><button class="link-btn" data-edit-event="${e.id}">수정</button><button data-delete-event="${e.id}">×</button></div>`).join(''):'<div class="empty">이 날짜에는 일정이 없습니다.</div>';const runnable=state.habits.filter(h=>habitRunsOn(day,h.schedule));$('#selectedHabits').innerHTML=runnable.length?runnable.map(h=>`<div class="mini-item"><button class="check ${checks.get(h.id)?'done':''}" data-habit-toggle="${h.id}" data-day="${day}"><span>${checks.get(h.id)?'✓':''}</span></button><div class="body"><strong>${esc(h.name)}</strong><span>${habitScheduleLabel(h.schedule)}</span></div></div>`).join(''):'<div class="empty">이 날짜에 예정된 체크리스트가 없습니다.</div>';$('#habitTemplateList').innerHTML=state.habits.map(h=>`<div class="row"><div><span style="font-size:11px">${esc(h.name)}</span><small class="muted" style="display:block;font-size:9px">${habitScheduleLabel(h.schedule)}</small></div><span class="spacer"></span><button class="link-btn" data-edit-habit="${h.id}">수정</button><button class="link-btn danger" data-delete-habit="${h.id}">삭제</button></div>`).join('')}
  function renderGoalInputs(){const f=state.goals.find(g=>g.kind==='final'),m=state.goals.find(g=>g.kind==='monthly');$('#finalGoalInput').value=f?.title||'';$('#finalGoalDeadline').value=f?.deadline||'';$('#monthlyGoalInput').value=m?.title||''}
  async function addEvent(){const name=$('#eventName').value.trim(),start=$('#eventStart').value,end=$('#eventEnd').value||start;if(!name)return toast('일정 내용을 입력해 주세요.');if(!start||!end||end<start)return toast('일정 날짜 범위를 확인해 주세요.');if(state.eventEdit){await withError(()=>DB.updateEvent(state.eventEdit.id,name,start,end),'일정 수정');state.eventEdit=null;$('#eventAdd').textContent='일정 추가';$('#eventCancel').classList.add('hidden');toast('일정을 수정했습니다.')}else{await withError(()=>DB.addEvent(name,start,end),'일정 추가');toast('일정을 추가했습니다.')}$('#eventName').value='';await loadCalendar()}
