  async function toggleEvent(id,done){await withError(()=>DB.toggleEvent(id,!done),'일정 체크');if(state.page==='today')await loadToday();else await loadCalendar()}
  async function toggleHabit(id,day){const current=state.page==='today'?null:checksMapFor(day).get(id);let done=current;if(state.page==='today'){const d=await DB.dashboard(day);done=new Map(d.checks.map(c=>[c.habit_id,c.completed])).get(id)}const habit=state.habits.find(h=>h.id===id);if(!done&&habit?.schedule?.type==='weekly_n'){const d=new Date(`${day}T00:00:00`),monday=new Date(d);monday.setDate(d.getDate()-((d.getDay()+6)%7));const start=dateKey(monday),end=new Date(monday);end.setDate(monday.getDate()+6);const count=state.habitChecks.filter(c=>c.habit_id===id&&c.completed&&c.day>=start&&c.day<=dateKey(end)).length;if(count>=Number(habit.schedule.count||1))return toast(`이번 주에는 이미 ${habit.schedule.count||1}회 완료했습니다.`)}await withError(()=>DB.setHabitCheck(id,day,!done),'체크 저장');if(state.page==='today')await loadToday();else await loadCalendar()}
